def prior_evidence():
    data=json.loads(previous.EVIDENCE.read_text(encoding='utf-8'));previous.validate(data);return data

def source_fingerprints():
    owners=dict(parent=previous,fixture=controls,identifier_model=identifier_model,reference_model=reference_model,diagnostics_model=diagnostics_model,objects_model=objects_model,oracle=oracle)
    return dict(publication_verifier_sha256=sha256(Path(__file__)),owners={k:sha256(Path(v.__file__)) for k,v in owners.items()},inherited=previous.source_fingerprints())

def provenance(parent):
    return dict(parent_evidence_sha256=sha256(previous.EVIDENCE),parent_case_result_sha256=digest(parent['case_result']),inherited_input_provenance=parent['input_provenance'],native_snapshot_used_as_python_model_input=False)

